      { id: 2, title: "The Reformation", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Age of Exploration", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Scientific Revolution", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Enlightenment", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
