  {
    lesson_number: 5,
    title: "World Wars Era",
    videos: [
      { id: 1, title: "World War I", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Interwar Period", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "World War II", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Holocaust", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Pacific Theater", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 6,
    title: "Cold War Era",
    videos: [
      { id: 1, title: "Cold War Beginnings", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Korean War", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Cuban Missile Crisis", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Vietnam War", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Space Race", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 7,
    title: "Decolonization & Independence",
    videos: [
      { id: 1, title: "Indian Independence", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "African Decolonization", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
