    videos: [
      { id: 1, title: "End of Cold War", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Digital Revolution", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Globalization", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "9/11 & War on Terror", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "21st Century Challenges", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 9,
    title: "Social & Cultural History",
    videos: [
      { id: 1, title: "Women's Movements", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Civil Rights Movements", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "LGBTQ+ History", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Environmental Movement", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Cultural Revolutions", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  },
  {
    lesson_number: 10,
    title: "U.S. History Summary",
    videos: [
      { id: 1, title: "Colonial Period", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 2, title: "Early Republic", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 3, title: "Civil War & Reconstruction", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 4, title: "Industrial Age & Progressivism", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" },
      { id: 5, title: "Modern America", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }
    ]
  }
];

export default function History() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  useEffect(() => {
    setSub("History");
    setLessons(HISTORY_LESSONS);
    setLoading(false);
  }, []);

  if (loading) return <div>Loading...</div>;

  const handleLessonClick = (lesson) => {
    navigate("/lesson", { state: { lesson } });
  };

  return (
    <div className="page-container">
      <Sidebar />
      <div className="content">
        <h1>{sub}</h1>
        <div className="lessons-grid">
          {lessons.map((lesson) => (
            <div key={lesson.lesson_number} className="lesson-card" onClick={() => handleLessonClick(lesson)}>
              <h3>Lesson {lesson.lesson_number}</h3>
              <p>{lesson.title}</p>
              <span className="video-count">{lesson.videos.length} videos</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
